
/* Hero: shuffling particle portraits. 5 faces sampled to point clouds, rendered in brand
   tones (espresso/orange/mustard) as tiny dots. Drifts & shimmers, a scan line sweeps,
   points scatter a little on hover, and the field cross-dissolves to the next face every 10s. */
(function(){
  var cv=document.getElementById('face'); if(!cv) return;
  var reduce=matchMedia('(prefers-reduced-motion:reduce)').matches;
  var mobile=Math.min(innerWidth,innerHeight)<700||matchMedia('(pointer:coarse)').matches;
  var W=560,H=680; var ctx=cv.getContext('2d');
  var CLOUDS=["","","","",""];
  function lp(a,b,t){return a+t*(b-a);}
  var RAMP=[];for(var d=0;d<256;d++){var D=d/255,r,g,b;
    if(D<0.42){var u=D/0.42;r=lp(226,202,u);g=lp(188,94,u);b=lp(122,42,u);}
    else if(D<0.72){var u=(D-0.42)/0.30;r=lp(202,122,u);g=lp(94,60,u);b=lp(42,36,u);}
    else{var u=(D-0.72)/0.28;r=lp(122,46,u);g=lp(60,34,u);b=lp(36,24,u);}
    RAMP[d]=(r|0)+','+(g|0)+','+(b|0);}
  function decode(b64){
    var bin=atob(b64),bytes=new Uint8Array(bin.length);for(var i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
    var dv=new DataView(bytes.buffer),n=(bytes.length/5)|0,pts=new Array(n);
    for(var i=0,o=0;i<n;i++,o+=5){var hx=dv.getUint16(o,true),hy=dv.getUint16(o+2,true);
      pts[i]={hx:hx,hy:hy,x:hx,y:hy,vx:0,vy:0,D:dv.getUint8(o+4),ph:(hx*12.9898+hy*78.233)};}

    return pts;
  }
  var fields=CLOUDS.map(decode);
  var cur=0,nxt=-1,mix=0;
  var mx=-9999,my=-9999,hover=false;
  /* cover-fit the 560x680 field into the panel at device resolution */
  var sx=1,ox=0,oy=0,dpr=1;
  function fit(){
    var r=cv.getBoundingClientRect();
    dpr=Math.min(2,window.devicePixelRatio||1);
    cv.width=Math.max(2,Math.round(r.width*dpr)); cv.height=Math.max(2,Math.round(r.height*dpr));
    sx=Math.max(cv.width/W, cv.height/H);
    ox=(cv.width-W*sx)/2; oy=(cv.height-H*sx)*0.30; /* bias up so face sits high, neck cut at bottom */
  }
  fit(); addEventListener('resize',fit);
  function toBuf(e){var r=cv.getBoundingClientRect();var cxp=(e.clientX-r.left)*(cv.width/r.width),cyp=(e.clientY-r.top)*(cv.height/r.height);mx=(cxp-ox)/sx;my=(cyp-oy)/sx;}
  if(!mobile){cv.addEventListener('pointermove',function(e){hover=true;toBuf(e);});cv.addEventListener('pointerleave',function(){hover=false;mx=my=-9999;});}
  var scanY=-70,SCANSPD=0.15,SCANBAND=26;
  var run=false,last=0,t=0, R=Math.max(70,W*0.13), R2=R*R;
  function drawField(pts,gAlpha){
    for(var i=0;i<pts.length;i++){var p=pts[i];
      var sb=0,nd=Math.abs(p.hy-scanY); if(nd<SCANBAND)sb=(1-nd/SCANBAND);
      var s1=Math.sin(t*0.5+p.ph), s2=Math.sin(t*0.42+p.ph*1.7);
      var tx=p.hx+1.2*s1, ty=p.hy+1.2*s2;
      var ax=(tx-p.x)*0.06+s1*0.05, ay=(ty-p.y)*0.06+s2*0.05-sb*0.4;
      if(hover){var dx=p.x-mx,dy=p.y-my,d2=dx*dx+dy*dy;if(d2<R2){var dd=Math.sqrt(d2)||1;var fo=(1-dd/R)*2.4;ax+=dx/dd*fo;ay+=dy/dd*fo;}}
      p.vx=(p.vx+ax)*0.84; p.vy=(p.vy+ay)*0.84; p.x+=p.vx; p.y+=p.vy;
      var a=(0.36+(p.D/255)*0.60)*gAlpha+sb*0.30; if(a<=0.02)continue;
      var X=ox+p.x*sx, Y=oy+p.y*sx;
      if(sb>0){ctx.fillStyle='rgba(240,190,88,'+Math.min(1,a)+')';}
      else ctx.fillStyle='rgba('+RAMP[p.D]+','+a.toFixed(3)+')';
      var sz=(2.05+sb*0.9)*sx; ctx.fillRect(X,Y,sz,sz);
    }
  }
  function frame(now){
    var dt=last?Math.min(50,now-last):16; last=now; t+=dt*0.06;
    scanY+=SCANSPD*dt; if(scanY>H+70)scanY=-70;
    if(nxt>=0){ mix+=dt/1500; if(mix>=1){cur=nxt;nxt=-1;mix=0;} }
    ctx.clearRect(0,0,cv.width,cv.height);
    if(nxt>=0){ drawField(fields[cur],1-mix); drawField(fields[nxt],mix); }
    else drawField(fields[cur],1);
    if(scanY>-16&&scanY<H+16){
      var y0=oy+(scanY-18)*sx, y1=oy+(scanY+18)*sx;
      var gg=ctx.createLinearGradient(0,y0,0,y1);
      gg.addColorStop(0,'rgba(200,85,31,0)');gg.addColorStop(0.5,'rgba(200,85,31,0.08)');gg.addColorStop(1,'rgba(200,85,31,0)');
      ctx.fillStyle=gg;ctx.fillRect(ox+30*sx,y0,(W-60)*sx,36*sx);
      ctx.fillStyle='rgba(200,85,31,0.4)';ctx.fillRect(ox+44*sx,oy+scanY*sx,(W-88)*sx,1.2*sx);
    }
  }
  if(reduce){fit();var pts=fields[0];ctx.clearRect(0,0,cv.width,cv.height);for(var i=0;i<pts.length;i++){var p=pts[i];ctx.fillStyle='rgba('+RAMP[p.D]+','+(0.32+(p.D/255)*0.64).toFixed(2)+')';ctx.fillRect(ox+p.hx*sx,oy+p.hy*sx,1.3*sx,1.3*sx);}return;}
  var timer=setInterval(function(){ if(nxt<0){ nxt=(cur+1)%fields.length; mix=0; } },10000);
  function loop(now){ if(run)frame(now||performance.now()); requestAnimationFrame(loop); }
  loop();
  if('IntersectionObserver' in window){ new IntersectionObserver(function(es){es.forEach(function(e){run=e.isIntersecting;if(run)last=0;});},{threshold:.02}).observe(cv); } else run=true;
})();
